UPDATE message_board
SET expired_at = #{now}
WHERE id = #{id}
  AND is_deleted = 1
  AND moderation_status = 0
  AND expired_at IS NULL
  AND restore_deadline = #{restoreDeadline}
  AND restore_deadline <= #{now}

