SELECT mb.*, u.user_name, u.user_avatar
FROM message_board mb
LEFT JOIN user u ON mb.user_id = u.id
WHERE mb.user_id = #{userId}
  AND mb.is_deleted = 1
  AND mb.moderation_status = 0
  AND mb.expired_at IS NULL
  AND mb.restore_deadline > #{now}
ORDER BY mb.deleted_at DESC, mb.id DESC
LIMIT #{size} OFFSET #{current}
